/*
"Iridescent Plasma Blob"
Kypo
*/


// just a random pallete really to mimick iridescent
vec3 palePink = vec3(0.98, 0.87, 0.89);
vec3 lavender = vec3(0.90, 0.85, 0.98);
vec3 lightSkyBlue = vec3(0.85, 0.91, 0.98);
vec3 mintGreen = vec3(0.85, 0.98, 0.90);
vec3 softPeach = vec3(0.98, 0.90, 0.85);
vec3 pearlWhite = vec3(0.98, 0.98, 0.98);
vec3 vibrantFuchsia = vec3(0.95, 0.20, 0.80);
vec3 goldAccent = vec3(1.00, 0.84, 0.00);
vec3 teal = vec3(0.00, 0.80, 0.80);
vec3 blushRose = vec3(0.95, 0.75, 0.75);
vec3 crystalPurple = vec3(0.80, 0.60, 0.95);
vec3 subtleAqua = vec3(0.70, 0.95, 0.95);
vec3 neonMagenta = vec3(1.00, 0.00, 0.80);
vec3 opalYellow = vec3(0.98, 0.98, 0.80);

mat2 m(float a) {
    float c = cos(a), s = sin(a);
    return mat2(c, -s, s, c);
}

float map(vec3 p) {
    p.xz *= m(iTime * 0.0);
    p.xy *= m(iTime * 0.5);
    vec3 q = p * 2.0 + iTime;
    return length(p + vec3(sin(iTime * 0.7))) * log(length(p) + 1.0) + sin(q.x + sin(q.z + sin(q.y))) * 0.5 - 1.0;
}

vec3 getIridescentColor(float t) {
    float cycle = fract(t);
    vec3 color;

    if (cycle < 0.07) color = mix(palePink, lavender, cycle / 0.07);
    else if (cycle < 0.14) color = mix(lavender, lightSkyBlue, (cycle - 0.07) / 0.07);
    else if (cycle < 0.21) color = mix(lightSkyBlue, mintGreen, (cycle - 0.14) / 0.07);
    else if (cycle < 0.28) color = mix(mintGreen, softPeach, (cycle - 0.21) / 0.07);
    else if (cycle < 0.35) color = mix(softPeach, pearlWhite, (cycle - 0.28) / 0.07);
    else if (cycle < 0.42) color = mix(pearlWhite, vibrantFuchsia, (cycle - 0.35) / 0.07);
    else if (cycle < 0.49) color = mix(vibrantFuchsia, goldAccent, (cycle - 0.42) / 0.07);
    else if (cycle < 0.56) color = mix(goldAccent, teal, (cycle - 0.49) / 0.07);
    else if (cycle < 0.63) color = mix(teal, blushRose, (cycle - 0.56) / 0.07);
    else if (cycle < 0.70) color = mix(blushRose, crystalPurple, (cycle - 0.63) / 0.07);
    else if (cycle < 0.77) color = mix(crystalPurple, subtleAqua, (cycle - 0.70) / 0.07);
    else if (cycle < 0.84) color = mix(subtleAqua, neonMagenta, (cycle - 0.77) / 0.07);
    else if (cycle < 0.91) color = mix(neonMagenta, opalYellow, (cycle - 0.84) / 0.07);
    else color = mix(opalYellow, palePink, (cycle - 0.91) / 0.09);

    return color;
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 a = (fragCoord.xy / iResolution.y - vec2(iResolution.x/iResolution.y * 0.5, 0.5));
    vec3 cl = vec3(0.0);
    float d = 0.0;

    for (int i = 0; i <= 5; i++) {
        vec3 p = vec3(0, 0, 5.0) + normalize(vec3(a, -1.0)) * d;
        float rz = map(p);
        float f = clamp((rz - map(p + 0.1)) * 0.5, -0.1, 1.0);

        vec3 color = getIridescentColor(f + float(i) * 0.15 + iTime * 0.1);
        cl = cl * color + smoothstep(2.5, 0.0, rz) * 0.6 * color;

        d += min(rz, 2.5);
    }

    fragColor = vec4(cl, 1.0);
}
